import pandas as pd
def clean(df):
    df = df.copy()
    # strip whitespace variants (Category: ' Furniture', ' Electronics', 'Office Supplies ')
    for col in df.select_dtypes(include=['object']).columns:
        df[col] = df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # fix Price written as text e.g. "$300.00"
    if 'Price' in df.columns:
        df['Price'] = df['Price'].astype(str).str.replace(r'[\$,]', '', regex=True).str.strip()
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    # ensure Quantity numeric and filter invalid (min 1, negative)
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
        df = df[df['Quantity'] >= 1]
    # optional: recompute Revenue = Quantity * Price to fix cross-column
    if 'Revenue' in df.columns and 'Quantity' in df.columns and 'Price' in df.columns:
        df['Revenue'] = pd.to_numeric(df['Revenue'], errors='coerce')
    # drop exact duplicate rows (1 duplicate) and keep Order_ID unique
    df = df.drop_duplicates()
    if 'Order_ID' in df.columns:
        df = df.drop_duplicates(subset=['Order_ID'], keep='first')
    return df

def answer(df):
    df = clean(df)
    if 'Region' not in df.columns or 'Quantity' not in df.columns:
        return {}
    df = df.dropna(subset=['Region'])
    df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    grouped = df.groupby('Region', dropna=True)['Quantity'].sum()
    result = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        # return int when whole number
        result[str(k)] = int(v) if float(v).is_integer() else float(v)
    return result
